/** @return array{errors:list<string>,warnings:list<string>,metrics:array<string,int>} */
function nexoraAnalyzeN10TargetSupplyChainContracts(string $root): array { $errors=[];$read=static fn(string $p):string=>is_file($p)?(string)file_get_contents($p):'';$required=['config/nexora-supply-chain.php','scripts/lib/release-trust-anchor.php','scripts/release-trust-anchor.php','scripts/release-trust-anchor.bat','scripts/release-trust-anchor.ps1','scripts/release-trust-anchor.sh','scripts/dependency-sbom.php','scripts/lib/production-dependency-stage.php','scripts/production-dependency-stage.php','scripts/release-provenance.php','scripts/lib/release-content-manifest.php'];foreach($required as $f)if(!is_file($root.'/'.$f)||filesize($root.'/'.$f)===0)$errors[]="missing v2.6 supply-chain artifact [{$f}]";$offline=$read($root.'/scripts/release-offline-verify.php');foreach(['expected-public-key-sha256','trust-anchor','external trust anchor','nexoraValidateReleaseContentManifest'] as $m)if(!str_contains($offline,$m))$errors[]="offline identity/content verification missing [{$m}]";$c1=$read($root.'/scripts/n1-c1-dependency-certify.php');foreach(['dependency-sbom','dependency-sbom.php','dependency_sbom_sha256'] as $m)if(!str_contains($c1,$m))$errors[]="C1 SBOM gate missing [{$m}]";$builder=$read($root.'/scripts/build-production-release.php');foreach(['production-dependency-stage.php','nexora-content-manifest.json','release-provenance.json','dependency-sbom.json','vendor/','production_dependencies_sha256'] as $m)if(!str_contains($builder,$m))$errors[]="production supply-chain packaging missing [{$m}]";$seal=$read($root.'/scripts/lib/final-release-seal.php');foreach(['trust_anchor_sha256','dependency_sbom_sha256','production_dependencies_sha256','release_provenance_sha256','key_id'] as $m)if(!str_contains($seal,$m))$errors[]="final release seal supply-chain binding missing [{$m}]";$c6=$read($root.'/scripts/n1-c6-final-certify.php');foreach(['release-trust-anchor','production-runtime-stage','release-provenance'] as $m)if(!str_contains($c6,$m))$errors[]="C6 supply-chain gate missing [{$m}]";return ['errors'=>$errors,'warnings'=>[],'metrics'=>['trust_anchor_wrappers'=>count(array_filter(['scripts/release-trust-anchor.bat','scripts/release-trust-anchor.ps1','scripts/release-trust-anchor.sh'],fn($f)=>is_file($root.'/'.$f))),'sbom'=>is_file($root.'/scripts/dependency-sbom.php')?1:0,'production_no_dev_stage'=>str_contains($builder,'production-dependency-stage.php')?1:0,'content_manifest'=>str_contains($builder,'nexora-content-manifest.json')?1:0,'strict_identity'=>str_contains($offline,'expected-public-key-sha256')?1:0]]; }
